  args: {
    article: mockArticleNoImage,
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Quantum Mechanics')).toBeVisible();
    await expect(
      canvas.getByText(/fundamental theory in physics/)
    ).toBeVisible();
  },
};

